645	  private static toSenders = (
646	    rawSenders: unknown,
647	    currentUserId: string,
648	  ): {
649	    count: number;
650	    latestTimestamp: number;
651	    isHighlighted: boolean;
652	    senderIds: string[];
653	  } => {
654	    if (!rawSenders)
655	      return { count: 1, latestTimestamp: 0, isHighlighted: false, senderIds: [] };
656	
