private static toSenders = (
  rawSenders: unknown,
  currentUserId: string,
): {
  count: number;
  latestTimestamp: number;
  isHighlighted: boolean;
  senderIds: string[];
} => {
  if (!rawSenders)
    return { count: 1, latestTimestamp: 0, isHighlighted: false, senderIds: [] };

  if (Array.isArray(rawSenders)) {
    const timestamps = rawSenders
      .map((sender) => this.extractTimestamp(sender))
      .filter((timestamp) => timestamp > 0);
    const senderIds = rawSenders
      .map((sender) => this.extractSenderUserId(sender))
      .filter(Boolean);
    const isHighlighted = senderIds.some((id) => id === currentUserId);
    return {
      count: rawSenders.length || 1,
      latestTimestamp: timestamps[0] ?? 0,
      isHighlighted,
      senderIds,
    };
  }

  if (rawSenders instanceof Map) {
    const entries = Array.from(rawSenders.entries());
    const values = entries.map(([, sender]) => sender);
    const timestamps = values
      .map((sender) => this.extractTimestamp(sender))
      .filter((timestamp) => timestamp > 0);
    const senderIds = entries
      .map(([senderId, sender]) =>
        typeof senderId === "string" && senderId
          ? senderId
          : this.extractSenderUserId(sender),
      )
      .filter(Boolean);
    const isHighlighted = senderIds.some((id) => id === currentUserId);
    return {
      count: values.length || 1,
      latestTimestamp: timestamps[0] ?? 0,
      isHighlighted,
      senderIds,
    };
  }

  if (typeof rawSenders === "object") {
    const entries = Object.entries(rawSenders as Record<string, unknown>);
    const values = entries.map(([, sender]) => sender);
    const timestamps = values
      .map((sender) => this.extractTimestamp(sender))
      .filter((timestamp) => timestamp > 0);
    const senderIds = entries
      .map(([senderId, sender]) =>
        senderId || this.extractSenderUserId(sender),
      )
      .filter(Boolean);
    const isHighlighted = senderIds.some((id) => id === currentUserId);
    return {
      count: values.length || 1,
      latestTimestamp: timestamps[0] ?? 0,
      isHighlighted,
      senderIds,
    };
  }

  return { count: 1, latestTimestamp: 0, isHighlighted: false, senderIds: [] };
};

